-- Vegan: 22 recipes
insert into "CozyCookBookSchema".folders (id, name, blurb, user_id, is_public, position) values
  ('c19bcc36-60b3-5867-a608-8c7a61dd6865', 'Vegan', 'Entirely plant-based, and built so protein is never the afterthought — most mains clear 20 g a serving.', null, true, 4096)
on conflict (id) do update set name = excluded.name, blurb = excluded.blurb;

insert into "CozyCookBookSchema".recipes
  (id, title, ingredients, steps, folder_id, user_id, meal, is_public, position)
select r.id, r.title,
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'name', n, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.ing) with ordinality as t(n, o)),
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'text', st, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.steps) with ordinality as t(st, o)),
  'c19bcc36-60b3-5867-a608-8c7a61dd6865', null, r.meal, true, r.pos
from (values
  ('8c7b7144-2e13-5469-9946-d17d71ae2f75'::uuid, 'Tofu Scramble', array['1 block firm tofu, crumbled','1/2 tsp ground turmeric','2 tbsp nutritional yeast','1 red bell pepper, diced','1 yellow onion, diced','2 cups spinach','1 tbsp olive oil','1/4 tsp black salt','Black pepper to taste'], array['Press the tofu 20 minutes, then crumble it unevenly so some pieces stay chunky.','Soften the onion and pepper in oil.','Add the tofu, turmeric and nutritional yeast and fry until the edges catch.','Wilt the spinach through at the end.','Black salt is what makes it taste of egg. Add it off the heat.'], 'Breakfast', 0),
  ('ba156776-e6b8-57a1-abd3-bb08dfb9b137'::uuid, 'High-Protein Overnight Oats', array['1 cup rolled oats','1 1/2 cups soy milk','1/4 cup chia seeds','1 scoop pea protein powder','2 tbsp peanut butter','1 banana, sliced','1 tbsp maple syrup','1 cup blueberries'], array['Whisk the protein powder into the soy milk first, or it clumps.','Stir in the oats, chia and peanut butter.','Refrigerate overnight.','Top with banana and blueberries. About 32 g of protein.'], 'Breakfast', 1024),
  ('8c8a86eb-36e7-5953-afcc-6fdfe3f6389e'::uuid, 'Chickpea Flour Omelette', array['1 cup chickpea flour','1 1/4 cups water','2 tbsp nutritional yeast','1/4 tsp black salt','1/2 tsp baking powder','1 cup cremini mushrooms, sliced','2 cups spinach','2 tbsp olive oil','Black pepper to taste'], array['Whisk the batter smooth and rest it 15 minutes.','Cook the mushrooms hard until they brown, then the spinach.','Pour the batter into an oiled pan and cook covered on low 6 minutes.','Add the filling to one half and fold. Around 20 g of protein.'], 'Breakfast', 2048),
  ('2c325daa-9135-598d-aa1b-2a3851784f68'::uuid, 'Seitan Breakfast Sausage', array['1 cup vital wheat gluten','1/4 cup nutritional yeast','1 cup vegetable stock','2 tbsp soy sauce','1 tsp fennel seeds','1 tsp sweet paprika','1 tsp fresh sage','2 cloves garlic, minced','1 tbsp olive oil'], array['Mix the dry ingredients, then the wet, and knead two minutes — no longer or it turns rubbery.','Roll into logs, wrap in foil, and steam 40 minutes.','Cool completely; the texture sets as it cools.','Slice and fry in oil until crisp. Roughly 21 g of protein per serving.'], 'Breakfast', 3072),
  ('ebc9c73b-eae5-5bed-a8db-7b0b1923f2dc'::uuid, 'Lentil Walnut Bolognese', array['1 cup red lentils','1 cup walnuts, chopped','1 cup mirepoix','3 cloves garlic, minced','1 can crushed tomatoes','2 tbsp tomato paste','1 cup vegetable stock','2 tbsp olive oil','1 lb spaghetti','1/4 cup fresh basil'], array['Toast the walnuts and chop them to the size of mince.','Soften the mirepoix slowly, then add the garlic and tomato paste and cook it dark.','Add lentils, tomatoes, walnuts and stock and simmer 40 minutes.','It should be thick enough to hold a spoon upright. About 24 g of protein a bowl.'], 'Lunch', 4096),
  ('88d2215e-84ec-534f-a680-f3b0adfa57eb'::uuid, 'Buffalo Cauliflower Wrap', array['1 head cauliflower, florets','1/2 cup chickpea flour','1/2 cup water','1/2 cup hot sauce','2 tbsp olive oil','4 tortillas','2 cups romaine lettuce, shredded','1/2 cup vegan ranch','1 carrot, julienned'], array['Coat the florets in a chickpea-flour batter and bake at 450°F for 20 minutes.','Toss in hot sauce and oil, then bake 10 minutes more so the sauce sets rather than sogs.','Build the wraps with lettuce, carrot and ranch.'], 'Lunch', 5120),
  ('5bba110c-4ea2-508b-bd22-52a140f2fc79'::uuid, 'Tempeh Banh Mi', array['8 oz tempeh, sliced','3 tbsp soy sauce','1 tbsp maple syrup','1 baguette','1 cup daikon radish, julienned','1 carrot, julienned','1/2 cup rice vinegar','1/4 cup fresh cilantro','1 jalapeño, sliced','3 tbsp vegan mayonnaise'], array['Pickle the daikon and carrot in vinegar with a little sugar and salt for an hour.','Steam the tempeh 10 minutes to take out the bitterness — this step matters.','Marinate in soy and maple, then pan-fry until glazed.','Build with mayonnaise, tempeh, pickles, cilantro and jalapeño. Around 22 g of protein.'], 'Lunch', 6144),
  ('bbbfc91e-3e79-54ef-b770-2609072c260e'::uuid, 'Red Lentil Dal', array['1 cup red lentils','1 yellow onion, diced','3 cloves garlic, minced','1 inch fresh ginger, grated','1 tsp ground turmeric','1 tsp ground cumin','1 can coconut milk','2 tbsp coconut oil','10 fresh curry leaves','1/4 cup fresh cilantro'], array['Simmer the lentils with turmeric until they collapse, about 20 minutes.','Temper cumin and curry leaves in coconut oil, then soften the onion, garlic and ginger.','Stir the tempering into the dal with the coconut milk.','Simmer 10 minutes more. About 18 g of protein a serving.'], 'Lunch', 7168),
  ('5c77e89a-c2a7-52dd-9874-cdc8a1d0f9e4'::uuid, 'Black Bean Burger', array['2 cans black beans, drained','1/2 cup rolled oats','1 yellow onion, minced','3 cloves garlic, minced','1 tbsp ground cumin','2 tbsp tomato paste','1/4 cup vital wheat gluten','4 burger buns','1 avocado, sliced'], array['Roast the beans 15 minutes to dry them out — wet beans make mushy burgers.','Pulse half with the oats and aromatics; leave the rest whole for texture.','Knead in the wheat gluten and chill an hour.','Sear hard in a pan, 4 minutes a side. About 19 g of protein.'], 'Lunch', 8192),
  ('58535853-034a-50f2-bcdf-eb1538b149b5'::uuid, 'Crispy Tofu Pad Thai', array['1 block extra-firm tofu, cubed','8 oz rice noodles','3 tbsp cornstarch','3 tbsp tamarind paste','3 tbsp soy sauce','2 tbsp maple syrup','2 cups mung bean sprouts','1/4 cup peanuts, crushed','4 green onions, sliced','2 tbsp sesame oil','1 lime'], array['Press the tofu, toss in cornstarch, and fry until every side is crisp.','Soak the noodles in hot water rather than boiling them.','Whisk tamarind, soy and maple into a sauce.','Stir-fry noodles and sauce hard and fast, then fold in tofu and sprouts.','Peanuts, green onion and lime at the table. Around 26 g of protein.'], 'Dinner', 9216),
  ('3b0c2664-7c8f-53f7-933f-2667b226f216'::uuid, 'Chana Masala with Spinach', array['2 cans chickpeas','1 yellow onion, minced','3 tomatoes, pureed','1 tbsp ginger garlic paste','2 tsp garam masala','1 tsp ground cumin','4 cups spinach','3 tbsp coconut oil','1/4 cup fresh cilantro'], array['Brown the onion thoroughly, then the ginger garlic paste.','Add tomato and spices and cook until the oil separates out.','Add the chickpeas and simmer 20 minutes, crushing some against the pan.','Wilt the spinach in at the end. About 20 g of protein.'], 'Dinner', 10240),
  ('ae53399a-2b56-534f-a1b1-15f09cf8be54'::uuid, 'Seitan Stir-Fry', array['1 lb seitan, sliced','3 cups stir-fry vegetable mix','3 cloves garlic, minced','1 inch fresh ginger, minced','3 tbsp soy sauce','1 tbsp sesame oil','1 tbsp cornstarch','1 tbsp maple syrup','2 cups cooked rice'], array['Get the wok properly hot before anything goes in.','Sear the seitan until browned at the edges, then remove it.','Stir-fry the vegetables two minutes, keeping them crunchy.','Return the seitan with the sauce and toss until it glazes. Roughly 34 g of protein.'], 'Dinner', 11264),
  ('bfd33eb9-0b21-557c-8a02-81f7837a33d7'::uuid, 'Mushroom Bourguignon', array['2 lbs cremini mushrooms, halved','1 cup mirepoix','3 cloves garlic, minced','2 cups red wine','2 cups vegetable stock','2 tbsp tomato paste','3 tbsp olive oil','2 tbsp all-purpose flour','2 fresh thyme sprigs','4 russet potatoes, mashed'], array['Brown the mushrooms in batches. Crowding them steams them and you lose the whole dish.','Soften the mirepoix, add garlic, tomato paste and flour.','Deglaze with the wine and reduce by half.','Add stock, mushrooms and thyme; simmer 40 minutes.','Serve over mashed potato.'], 'Dinner', 12288),
  ('4e6b1630-be4e-5794-8607-38908d3b5821'::uuid, 'Coconut Chickpea Curry', array['2 cans chickpeas','1 can coconut milk','1 yellow onion, diced','3 cloves garlic, minced','1 tbsp red curry paste','1 red bell pepper, sliced','2 cups spinach','2 tbsp coconut oil','1 lime','1/4 cup fresh cilantro'], array['Fry the curry paste in coconut oil for a minute until it smells fragrant.','Add onion, garlic and pepper and soften.','Add chickpeas and coconut milk and simmer 20 minutes.','Spinach, lime and cilantro at the end.'], 'Dinner', 13312),
  ('f9d23d11-765f-54fd-a764-c6cb099ac1f9'::uuid, 'Tofu Tikka Masala', array['1 block extra-firm tofu, cubed','1 cup coconut yogurt','2 tbsp ginger garlic paste','2 tsp garam masala','1 can crushed tomatoes','1 cup coconut milk','1 yellow onion, minced','3 tbsp coconut oil','1 tbsp kasuri methi'], array['Press and marinate the tofu in coconut yogurt and spices two hours.','Broil until charred at the corners.','Cook the onion, tomatoes and remaining spices down, then blend smooth.','Add coconut milk and the tofu. Crush kasuri methi over at the end. Around 24 g of protein.'], 'Dinner', 14336),
  ('27d0bc9c-e835-534d-83f2-63ee36f7a187'::uuid, 'Hummus', array['2 cans chickpeas','1/2 cup tahini','3 tbsp lemon juice','2 cloves garlic','1/4 tsp ground cumin','3 tbsp olive oil','1/4 tsp baking soda'], array['Simmer the chickpeas with baking soda 20 minutes until the skins slip off.','Blend the tahini, lemon and garlic first until it seizes and goes pale.','Add the warm chickpeas and blend for a full five minutes.','Time in the blender is what makes it silky.'], 'Snack', 15360),
  ('f56b690d-d01d-51c4-80b5-100e6f4b7757'::uuid, 'Roasted Chickpeas', array['2 cans chickpeas','2 tbsp olive oil','1 tsp sweet paprika','1 tsp ground cumin','1/2 tsp cayenne','Salt to taste'], array['Dry the chickpeas completely on a towel.','Toss with oil and roast at 400°F for 35 minutes, shaking the tray twice.','Add the spices after roasting, not before, or they scorch.'], 'Snack', 16384),
  ('d4028bee-45c0-5ea4-8504-7fb4281e4649'::uuid, 'Peanut Butter Protein Balls', array['1 cup rolled oats','1/2 cup peanut butter','1/3 cup maple syrup','2 scoops pea protein powder','1/4 cup ground flaxseed','1/4 cup chocolate chips','1 tsp vanilla extract'], array['Mix everything into a stiff dough, adding a splash of plant milk if needed.','Chill 30 minutes, then roll into balls.','Keep refrigerated. Around 8 g of protein each.'], 'Snack', 17408),
  ('ad5733cb-cbb9-57b1-a0ac-2f56ad914941'::uuid, 'Vegan Chocolate Mousse', array['1 block silken tofu','200g dark chocolate, melted','3 tbsp maple syrup','1 tsp vanilla extract','Pinch of salt','1 cup raspberries'], array['Blend the silken tofu completely smooth before anything else goes in.','Melt the chocolate and blend it in while warm.','Add maple, vanilla and salt.','Chill four hours. Nobody guesses it is tofu.'], 'Snack', 18432),
  ('be0516d8-84ec-5a17-a80c-bc7cfa64a057'::uuid, 'Banana Nice Cream', array['4 bananas, frozen','2 tbsp peanut butter','2 tbsp cocoa powder','1/4 cup soy milk','1 tsp vanilla extract'], array['Freeze sliced ripe bananas overnight.','Blend with as little milk as the machine will tolerate.','It goes gravelly, then suddenly creamy. Keep going through the gravelly stage.'], 'Snack', 19456),
  ('e04a5b0e-c82b-5100-bf53-0917b666f7ef'::uuid, 'Vegan Chocolate Chip Cookies', array['2 1/4 cups all-purpose flour','1 cup vegan butter','3/4 cup brown sugar','1/2 cup granulated sugar','1/4 cup aquafaba','2 tsp vanilla extract','1 tsp baking soda','1 tsp salt','2 cups chocolate chips'], array['Whip the aquafaba to soft peaks first — it is standing in for the egg.','Cream the vegan butter and sugars, then fold in the aquafaba.','Add the dry ingredients and chips and chill the dough overnight.','Bake at 375°F for 11 minutes.'], 'Snack', 20480),
  ('c059d543-a82a-57c0-86af-fde8d07a5a84'::uuid, 'Chia Pudding', array['1/2 cup chia seeds','2 cups coconut milk','2 tbsp maple syrup','1 tsp vanilla extract','1 cup mango, diced','2 tbsp pistachios'], array['Whisk the chia into the milk and wait five minutes, then whisk again — this stops clumping.','Refrigerate at least four hours.','Top with mango and pistachios.'], 'Snack', 21504)
) as r(id, title, ing, steps, meal, pos)
on conflict (id) do update set title = excluded.title, ingredients = excluded.ingredients, steps = excluded.steps, meal = excluded.meal;
